// ───────────────────────────── Tra cứu (viết tay, không sinh) ─────────────────────────────

export interface BrandQuery {
  /** id trong kho kết nối / id plugin / catalogId của server MCP. */
  id?: string;
  /** Tên hiển thị (tên plugin, tên server). */
  name?: string;
  /** Hãng (vendor của mục trong kho kết nối). */
  vendor?: string;
  /** Nguồn: "chủ/repo" của plugin, "anthropics", hoặc nguồn kỹ năng ("google-skills"…). */
  origin?: string;
  /** Địa chỉ server hoặc dòng lệnh (lấy tên miền / phạm vi npm "@hãng/…"). */
  url?: string;
}

export interface BrandMatch {
  key: string;
  logo: BrandLogo;
}

/** Bỏ dấu tiếng Việt, chữ thường, tách thành từ a-z0-9. */
export function brandTokens(s: string): string[] {
  return s
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter(Boolean);
}

/** Từ chung ở cuối tên ("…-skills", "…-lsp", "…-mcp") — bỏ đi khi so khớp. */
const GENERIC_TAIL = new Set(['skills', 'skill', 'agent', 'agents', 'plugin', 'plugins', 'mcp', 'server', 'cli', 'lsp', 'sdk', 'dev', 'api', 'toolkit', 'official', 'claude', 'code', 'ai', 'extension', 'extensions', 'kit']);
/** Tên gọi khác chỉ dùng khi KHỚP NGUYÊN VẸN — không dùng làm tiền tố (quá chung chung). */
const EXACT_ONLY = new Set(['memory', 'filesystem', 'claude', 'rc', 'pg', 'go', 'cpp', 'sequentialthinking']);
/** Plugin của bên thứ ba nằm trong kho chính thức của Anthropic: không lấy logo Anthropic theo nguồn. */
const THIRD_PARTY_IN_OFFICIAL = new Set(['serena']);
/**
 * Thương hiệu ĐÃ GỠ logo theo yêu cầu của chủ sở hữu (xem docs/BRAND-ASSETS.md "Đã gỡ"): mục mà chính id/tên là hãng đó phải hiện monogram,
 * không được rơi sang logo của hãng mẹ hay kho chứa (Playwright → Microsoft, csharp-lsp → Anthropic, Azure → Microsoft…).
 * Khớp theo dạng chuẩn hoá của id/tên (kể cả khi đã bỏ đuôi chung: "csharp-lsp" → csharp, "azure-skills" → azure).
 */
const NO_LOGO_BRANDS = new Set(['oracle', 'salesforce', 'adobe', 'twilio', 'slack', 'canva', 'azure', 'microsoftazure', 'playwright', 'zoho', 'sourcegraph', 'csharp']);
const OFFICIAL_ORIGINS = new Set(['anthropics', 'anthropic', 'anthropicclaudepluginsofficial']);

function hostLabel(u: string): string | undefined {
  const m = u.match(/^[a-z][a-z0-9+.-]*:\/\/([^/:?#\s]+)/i);
  if (!m) return undefined;
  const parts = m[1].toLowerCase().split('.').filter(Boolean);
  if (parts.length < 2) return parts[0];
  const sld = parts[parts.length - 2];
  // co.uk, com.vn…
  return parts.length >= 3 && /^(co|com|net|org|gov|edu)$/.test(sld) ? parts[parts.length - 3] : sld;
}

/** Ứng viên khớp từ một chuỗi: nguyên vẹn → bỏ đuôi chung → hai từ đầu → từ đầu. */
function shapes(raw: string): { exact: string[]; prefix: string[] } {
  const t = brandTokens(raw);
  if (t.length === 0) return { exact: [], prefix: [] };
  const exact = [t.join('')];
  const core = [...t];
  while (core.length > 1 && GENERIC_TAIL.has(core[core.length - 1])) core.pop();
  exact.push(core.join(''));
  const prefix: string[] = [];
  if (core.length > 2) prefix.push(core.slice(0, 2).join(''));
  if (core.length > 1) prefix.push(core[0]);
  // Cuối cùng: một từ riêng lẻ đủ dài ở vị trí khác ("db:postgres" → postgres).
  for (const w of core.slice(1)) if (w.length >= 4 && !prefix.includes(w)) prefix.push(w);
  return { exact, prefix };
}

function fieldsOf(q: BrandQuery): string[] {
  const out: string[] = [];
  const name = q.name ? brandTokens(q.name).join('') : '';
  if (q.id) out.push(q.id);
  if (q.name) out.push(q.name);
  if (q.vendor) out.push(q.vendor);
  // Nguồn ngoài GitHub là tên miền nơi lưu ("gitlab.com"): đó là nơi chứa, không phải thương hiệu của plugin → bỏ qua.
  if (q.origin && !(q.origin.includes('.') && !q.origin.includes('/'))) {
    const [owner, repo] = q.origin.split('/');
    const official = OFFICIAL_ORIGINS.has(brandTokens(owner).join(''));
    if (!(official && THIRD_PARTY_IN_OFFICIAL.has(name))) {
      if (repo) out.push(repo);
      out.push(owner);
    }
  }
  if (q.url) {
    const host = hostLabel(q.url);
    if (host) out.push(host);
    const scope = q.url.match(/(?:^|\s)@([a-z0-9][a-z0-9-]*)\//i);
    if (scope) out.push(scope[1]);
    const pkg = q.url.match(/(?:^|\s)([a-z0-9][a-z0-9-]*-mcp)(?:@|\s|$)/i);
    if (pkg) out.push(pkg[1]);
  }
  return out;
}

/**
 * Tìm logo cho một dịch vụ/plugin/nguồn kỹ năng; không có → undefined (dùng monogram).
 * Thứ tự: khớp nguyên vẹn ở mọi trường (id → tên → hãng → nguồn → địa chỉ), rồi mới khớp tiền tố.
 */
export function brandFor(q: BrandQuery): BrandMatch | undefined {
  for (const own of [q.id, q.name]) if (own && shapes(own).exact.some((s) => NO_LOGO_BRANDS.has(s))) return undefined;
  const fields = fieldsOf(q).map(shapes);
  const hit = (k: string | undefined): BrandMatch | undefined => (k && LOGOS[k] ? { key: k, logo: LOGOS[k] } : undefined);
  for (const f of fields) for (const [i, s] of f.exact.entries()) {
    // Dạng đã bỏ đuôi chung ("claude-plugins" → "claude") không được khớp các tên quá chung chung.
    if (i > 0 && EXACT_ONLY.has(s)) continue;
    const m = hit(BRAND_ALIASES[s]);
    if (m) return m;
  }
  for (const f of fields) for (const s of f.prefix) {
    if (EXACT_ONLY.has(s)) continue;
    const m = hit(BRAND_ALIASES[s]);
    if (m) return m;
  }
  return undefined;
}

// ───────────────────────────── Monogram ─────────────────────────────

const TLD = /\.(com|io|ai|dev|app|net|org|co|so|sh)$/i;

/** Chữ viết tắt (1–2 ký tự) + sắc độ cố định (0–359) cho mục không có logo. */
export function monogram(label: string): { text: string; hue: number } {
  const clean = label.trim().replace(TLD, '');
  const words = clean
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[đĐ]/g, (c) => (c === 'đ' ? 'd' : 'D'))
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean);
  let text = '';
  if (words.length >= 2) text = words[0][0] + words[1][0];
  else if (words.length === 1) {
    const caps = words[0].match(/[A-Z]/g);
    text = caps && caps.length >= 2 && words[0][0] === caps[0] ? caps[0] + caps[1] : words[0][0];
  }
  text = (text || '?').toUpperCase();
  let h = 2166136261;
  for (const ch of brandTokens(label).join('') || label) h = Math.imul(h ^ ch.charCodeAt(0), 16777619);
  return { text, hue: (h >>> 0) % 360 };
}

// ───────────────────────────── Màu glyph theo theme ─────────────────────────────

const rgb = (hex: string): [number, number, number] => {
  const h = hex.replace('#', '');
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)) as [number, number, number];
};
const lin = (c: number): number => {
  const s = c / 255;
  return s <= 0.03928 ? s / 12.92 : ((s + 0.055) / 1.055) ** 2.4;
};
export function luminance(hex: string): number {
  const [r, g, b] = rgb(hex).map(lin);
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
export function contrast(a: string, b: string): number {
  const [x, y] = [luminance(a), luminance(b)].sort((p, q) => q - p);
  return (x + 0.05) / (y + 0.05);
}
const toHex = (c: number[]): string => '#' + c.map((v) => Math.round(v).toString(16).padStart(2, '0')).join('').toUpperCase();
const mix = (a: string, b: string, t: number): string => {
  const [p, q] = [rgb(a), rgb(b)];
  return toHex(p.map((v, i) => v + (q[i] - v) * t));
};

/** Nền tham chiếu của từng theme (thanh bên VS Code) và độ tương phản tối thiểu của glyph (WCAG 1.4.11: 3:1; tương phản cao: 4.5:1). */
export const THEME_INK = {
  dark: { bg: '#1F1F1F', min: 3 },
  light: { bg: '#F8F8F8', min: 3 },
  hcDark: { bg: '#000000', min: 4.5 },
  hcLight: { bg: '#FFFFFF', min: 4.5 },
} as const;

/** Màu glyph cho một theme: giữ màu hãng nếu đủ tương phản, không thì pha dần với trắng (nền tối) / đen (nền sáng). */
export function inkFor(hex: string, theme: keyof typeof THEME_INK): string {
  const { bg, min } = THEME_INK[theme];
  const toward = luminance(bg) < 0.5 ? '#FFFFFF' : '#000000';
  for (let t = 0; t <= 1.0001; t += 0.05) {
    const c = mix(hex, toward, t);
    if (contrast(c, bg) >= min) return c;
  }
  return toward;
}

/** Chữ/glyph trên nền màu hãng (tông 'solid'). */
export function onSolid(hex: string): string {
  return contrast('#000000', hex) >= contrast('#FFFFFF', hex) ? '#111111' : '#FFFFFF';
}
